#!/usr/bin/env node
// Generates docs/RULES.md from the rule definitions. `--check` fails if the committed file is stale.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { RULES } from '../src/index.js';

const out = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'docs', 'RULES.md');
const fence = (s) => { let t = String(s); try { t = JSON.stringify(JSON.parse(t), null, 2); } catch { /* keep as is */ } return '```json\n' + t + '\n```'; };

const lines = [
  '# Rules', '', '<!-- generated by scripts/gen-rules-doc.js — do not edit by hand -->', '',
  '| ID | Name | Default severity | What it finds |', '|---|---|---|---|',
  ...RULES.map((r) => `| [${r.id}](#${r.id.toLowerCase()}-${r.name}) | \`${r.name}\` | ${r.severity} | ${r.title} |`), '',
  'Severity can be raised or lowered per finding by context (for example, a write reachable from an unauthenticated trigger is one level worse). Override a rule in `.n8nlintrc.json`: `{ "rules": { "N8N010": "off", "N8N002": "low" } }`.', '',
  'Suppress a single finding by putting `n8n-lint-disable N8N005` in the node\'s **Notes** field (with a reason). Suppress rules for a whole workflow with a sticky note containing `n8n-lint-disable-workflow` (all rules) or `n8n-lint-disable-workflow N8N003, N8N002`.', '',
];
for (const r of RULES) {
  lines.push(`## ${r.id} ${r.name}`, '', `**Default severity:** ${r.severity}  `, `**${r.title}**`, '', r.summary, '',
    `**Why it matters.** ${r.why}`, '', `**How to fix.** ${r.fix}`, '', '<details><summary>Example: before / after</summary>', '', 'Before:', '', fence(r.bad), '', 'After:', '', fence(r.good), '', '</details>', '');
}
const text = lines.join('\n');
if (process.argv.includes('--check')) {
  const cur = fs.existsSync(out) ? fs.readFileSync(out, 'utf8') : '';
  if (cur !== text) { console.error('docs/RULES.md is out of date. Run: npm run docs'); process.exit(1); }
  console.log('docs/RULES.md is up to date');
} else {
  fs.mkdirSync(path.dirname(out), { recursive: true });
  fs.writeFileSync(out, text);
  console.log('wrote docs/RULES.md');
}
